// Alev alarmı: alev sensörü ateşi görünce buzzer öter, LED yanıp söner.
const int ALEV_PIN = 7;
const int BUZZER_PIN = 8;
const int LED_PIN = 9;
const int ALEV_VAR = LOW;  // Çoğu modül alev görünce LOW verir. Tersse HIGH yaz.

bool oncekiAlev = false;

void setup() {
  Serial.begin(9600);
  pinMode(ALEV_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("Alev yok");
}

void loop() {
  bool alev = digitalRead(ALEV_PIN) == ALEV_VAR;

  // Yalnız durum değişince yaz.
  if (alev != oncekiAlev) {
    Serial.println(alev ? "ALEV VAR!" : "Alev yok");
    oncekiAlev = alev;
  }

  if (alev) {
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 2500);
    delay(150);
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
    delay(150);
  } else {
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
    delay(50);
  }
}
